  const rd=Math.tanh((act-inh*0.6+mod*0.4+bg*0.25+spiral+cell)*2);
  const rd2=Math.tanh((act*0.5+inh*0.3-mod*0.8+bg*0.4-spiral*0.5)*1.8);
